    57→          "confidence": { "type": "string", "enum": ["HIGH", "MEDIUM", "LOW"] },
    58→          "invalidationSignal": { "type": "string" }
    59→        }
    60→      },
    61→      "description": "Assumptions accepted for this dispatch"
    62→    }
    63→  },
    64→  "additionalProperties": false
    65→}
    66→'}]}

